'use client';

import { ark, type HTMLArkProps } from '@ark-ui/react/factory';
import {
  Tour as TourPrimitive,
  useTour,
  useTourContext,
  waitForElement,
  waitForElementValue,
  waitForEvent,
  waitForPromise,
} from '@ark-ui/react/tour';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import { CloseButton } from '../close-button';
import styles from './Tour.module.css';

type TourRootProps = ComponentProps<typeof TourPrimitive.Root> & OverlayPortalProps;
type TourCloseIconProps = Omit<ComponentProps<typeof TourPrimitive.CloseTrigger>, 'asChild'>;
type TourActionListProps = { className?: string };

function Tour({
  lazyMount = true,
  portalled,
  portalRef,
  unmountOnExit = true,
  ...props
}: TourRootProps) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <TourPrimitive.Root lazyMount={lazyMount} unmountOnExit={unmountOnExit} {...props} />
    </OverlayPortalProvider>
  );
}

const TourBackdrop = forwardRef<
  ComponentRef<typeof TourPrimitive.Backdrop>,
  ComponentProps<typeof TourPrimitive.Backdrop>
>(function TourBackdrop({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <TourPrimitive.Backdrop
        ref={ref}
        className={clsx(styles.backdrop, className)}
        {...props}
        data-slot="tour-backdrop"
      />
    </OverlayPortal>
  );
});

const TourSpotlight = forwardRef<
  ComponentRef<typeof TourPrimitive.Spotlight>,
  ComponentProps<typeof TourPrimitive.Spotlight>
>(function TourSpotlight({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <TourPrimitive.Spotlight
        ref={ref}
        className={clsx(styles.spotlight, className)}
        {...props}
        data-slot="tour-spotlight"
      />
    </OverlayPortal>
  );
});

const TourPositioner = forwardRef<
  ComponentRef<typeof TourPrimitive.Positioner>,
  ComponentProps<typeof TourPrimitive.Positioner>
>(function TourPositioner({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <TourPrimitive.Positioner
        ref={ref}
        className={clsx(styles.positioner, className)}
        {...props}
        data-slot="tour-positioner"
      />
    </OverlayPortal>
  );
});

const TourContent = forwardRef<
  ComponentRef<typeof TourPrimitive.Content>,
  ComponentProps<typeof TourPrimitive.Content>
>(function TourContent({ className, ...props }, ref) {
  return (
    <TourPrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="tour-content"
    />
  );
});

const TourArrow = forwardRef<
  ComponentRef<typeof TourPrimitive.Arrow>,
  ComponentProps<typeof TourPrimitive.Arrow>
>(function TourArrow({ className, children, ...props }, ref) {
  return (
    <TourPrimitive.Arrow
      ref={ref}
      className={clsx(styles.arrow, className)}
      {...props}
      data-slot="tour-arrow"
    >
      {children ?? <TourArrowTip />}
    </TourPrimitive.Arrow>
  );
});

const TourArrowTip = forwardRef<
  ComponentRef<typeof TourPrimitive.ArrowTip>,
  ComponentProps<typeof TourPrimitive.ArrowTip>
>(function TourArrowTip({ className, ...props }, ref) {
  return (
    <TourPrimitive.ArrowTip
      ref={ref}
      className={clsx(styles.arrowTip, className)}
      {...props}
      data-slot="tour-arrow-tip"
    />
  );
});

const TourTitle = forwardRef<
  ComponentRef<typeof TourPrimitive.Title>,
  ComponentProps<typeof TourPrimitive.Title>
>(function TourTitle({ className, ...props }, ref) {
  return (
    <TourPrimitive.Title
      ref={ref}
      className={clsx(styles.title, className)}
      {...props}
      data-slot="tour-title"
    />
  );
});

const TourDescription = forwardRef<
  ComponentRef<typeof TourPrimitive.Description>,
  ComponentProps<typeof TourPrimitive.Description>
>(function TourDescription({ className, ...props }, ref) {
  return (
    <TourPrimitive.Description
      ref={ref}
      className={clsx(styles.description, className)}
      {...props}
      data-slot="tour-description"
    />
  );
});

const TourProgressText = forwardRef<
  ComponentRef<typeof TourPrimitive.ProgressText>,
  ComponentProps<typeof TourPrimitive.ProgressText>
>(function TourProgressText({ className, ...props }, ref) {
  return (
    <TourPrimitive.ProgressText
      ref={ref}
      className={clsx(styles.progressText, className)}
      {...props}
      data-slot="tour-progress-text"
    />
  );
});

const TourBody = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(function TourBody(
  { className, ...props },
  ref,
) {
  return (
    <ark.div ref={ref} className={clsx(styles.body, className)} {...props} data-slot="tour-body" />
  );
});

const TourCloseTrigger = forwardRef<
  ComponentRef<typeof TourPrimitive.CloseTrigger>,
  ComponentProps<typeof TourPrimitive.CloseTrigger>
>(function TourCloseTrigger(props, ref) {
  return <TourPrimitive.CloseTrigger ref={ref} {...props} data-slot="tour-close-trigger" />;
});

const TourCloseIcon = forwardRef<ComponentRef<typeof CloseButton>, TourCloseIconProps>(
  function TourCloseIcon(
    { className, children, 'aria-label': ariaLabel = a11yLabels.closeTour, ...props },
    ref,
  ) {
    return (
      <TourPrimitive.CloseTrigger asChild {...props}>
        <CloseButton
          ref={ref}
          data-slot="tour-close-icon"
          aria-label={ariaLabel}
          className={clsx(styles.closeIcon, className)}
        >
          {children}
        </CloseButton>
      </TourPrimitive.CloseTrigger>
    );
  },
);

const TourControl = forwardRef<
  ComponentRef<typeof TourPrimitive.Control>,
  ComponentProps<typeof TourPrimitive.Control>
>(function TourControl({ className, ...props }, ref) {
  return (
    <TourPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="tour-control"
    />
  );
});

const TourActionTrigger = forwardRef<
  ComponentRef<typeof TourPrimitive.ActionTrigger>,
  ComponentProps<typeof TourPrimitive.ActionTrigger>
>(function TourActionTrigger({ asChild, className, ...props }, ref) {
  return (
    <TourPrimitive.ActionTrigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.actionTrigger, className)}
      {...props}
      data-slot="tour-action-trigger"
    />
  );
});

const TourActions = TourPrimitive.Actions;

function TourActionList({ className }: TourActionListProps) {
  return (
    <TourPrimitive.Actions>
      {(actions) =>
        actions.map((action, index) => (
          <TourActionTrigger
            key={`${action.label}-${index}`}
            action={action}
            className={className}
          />
        ))
      }
    </TourPrimitive.Actions>
  );
}

const TourContext = TourPrimitive.Context;

export {
  Tour,
  TourActionList,
  TourActionTrigger,
  TourActions,
  TourArrow,
  TourArrowTip,
  TourBackdrop,
  TourBody,
  TourCloseIcon,
  TourCloseTrigger,
  TourContent,
  TourContext,
  TourControl,
  TourDescription,
  TourPositioner,
  TourProgressText,
  TourSpotlight,
  TourTitle,
  useTour,
  useTourContext,
  waitForElement,
  waitForElementValue,
  waitForEvent,
  waitForPromise,
};

export type { TourActionListProps, TourCloseIconProps, TourRootProps };

export type {
  TourActionTriggerProps,
  TourActionsProps,
  TourArrowProps,
  TourArrowTipProps,
  TourBackdropProps,
  TourCloseTriggerProps,
  TourContentProps,
  TourContextProps,
  TourControlProps,
  TourDescriptionProps,
  TourPositionerProps,
  TourProgressTextProps,
  TourSpotlightProps,
  TourStatusChangeDetails,
  TourStepChangeDetails,
  TourStepDetails,
  TourStepEffectArgs,
  TourTitleProps,
  UseTourContext,
  UseTourProps,
  UseTourReturn,
  WaitForEventOptions,
  WaitOptions,
} from '@ark-ui/react/tour';

@layer moduix.components {
  /* Ark sets --tour-layer to 0 on the backdrop, 1 on the spotlight, and 2 on the positioner. */
  .backdrop,
  .spotlight,
  .positioner {
    z-index: calc(var(--moduix-z-tour) + var(--tour-layer, 0));
  }

  .backdrop {
    background-color: var(--moduix-backdrop-bg, var(--moduix-color-overlay));
    backdrop-filter: var(--moduix-backdrop-filter, blur(4px));

    &[data-state='open'] {
      animation: global(moduix-dialog-backdrop-in) var(--moduix-transition-default);
    }

    &[data-state='closed'] {
      animation: global(moduix-dialog-backdrop-out) var(--moduix-transition-default) forwards;
    }
  }

  .spotlight {
    box-shadow: 0 0 0 2px var(--moduix-color-ring);
  }

  .positioner {
    /* Ark builds the inline z-index of tooltip steps from this variable. */
    --tour-z-index: var(--moduix-z-tour);
    max-width: var(--available-width);
    max-height: var(--available-height);
    outline: 0;

    &[data-type='dialog'] {
      position: fixed;
      inset: 0;
      display: grid;
      /* Safe centering keeps the top of tall content reachable while the positioner scrolls. */
      place-items: safe center;
      overflow-y: auto;
      overscroll-behavior: contain;
      padding: var(--moduix-spacing-4);
    }

    /* Ark does not position floating steps; keep them at a viewport edge or in its center. */
    &[data-type='floating'] {
      --_tour-offset: var(--moduix-spacing-6);
      position: fixed;
      max-width: calc(100vw - 2 * var(--_tour-offset));
      max-height: calc(100dvh - 2 * var(--_tour-offset));

      &[data-placement^='top'] {
        top: var(--_tour-offset);
      }

      &[data-placement^='bottom'] {
        bottom: var(--_tour-offset);
      }

      &[data-placement^='left'] {
        left: var(--_tour-offset);
      }

      &[data-placement^='right'] {
        right: var(--_tour-offset);
      }

      &:is([data-placement='top'], [data-placement='bottom']) {
        left: 50%;
        translate: -50% 0;
      }

      &:is([data-placement='left'], [data-placement='right']) {
        top: 50%;
        translate: 0 -50%;
      }

      &[data-placement='center'] {
        top: 50%;
        left: 50%;
        translate: -50% -50%;
      }

      &:is([data-placement='top-start'], [data-placement='bottom-start']) {
        inset-inline-start: var(--_tour-offset);
      }

      &:is([data-placement='top-end'], [data-placement='bottom-end']) {
        inset-inline-end: var(--_tour-offset);
      }

      &:is([data-placement='left-start'], [data-placement='right-start']) {
        top: var(--_tour-offset);
      }

      &:is([data-placement='left-end'], [data-placement='right-end']) {
        bottom: var(--_tour-offset);
      }
    }
  }

  .content {
    --_tour-width: 20rem;
    box-sizing: border-box;
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--moduix-spacing-1);
    width: var(--_tour-width);
    max-width: min(calc(100vw - var(--moduix-spacing-8)), var(--available-width, 100vw));
    max-height: min(24rem, var(--available-height, 100dvh));
    padding: var(--moduix-spacing-5);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    box-shadow: var(--moduix-shadow-lg);
    outline: 0;
    transform-origin: var(--transform-origin);

    &[data-type='dialog'] {
      --_tour-width: 26rem;
    }

    &[data-type='floating'] {
      --_tour-width: 22rem;
    }

    &[data-state='open'] {
      /* A modal dialog disables pointer events outside itself; Ark keeps tour content as its branch. */
      pointer-events: auto;
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }
  }

  .arrow {
    --arrow-size: var(--moduix-spacing-2-5);
    --arrow-background: var(--moduix-color-popover);
  }

  .arrowTip {
    border-top: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-left: var(--moduix-border-width-sm) solid var(--moduix-color-border);
  }

  .title {
    margin: 0;
    /* Keeps the title clear of the absolutely positioned close icon. */
    padding-inline-end: var(--moduix-spacing-6);
    font-size: var(--moduix-text-md);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-md);
  }

  .description {
    margin: 0;
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .progressText {
    margin-block-start: var(--moduix-spacing-2);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
    line-height: var(--moduix-line-height-text-xs);
  }

  /* Shrinks within the content height limit and scrolls long step copy. */
  .body {
    display: flex;
    min-block-size: 0;
    flex-direction: column;
    gap: var(--moduix-spacing-1);
    overflow: auto;
  }

  .closeIcon {
    --moduix-close-button-radius: var(--moduix-radius-md);
    --moduix-close-button-bg-hover: var(--moduix-color-accent);
    --moduix-close-button-color-hover: var(--moduix-color-popover-foreground);
    position: absolute;
    inset-block-start: var(--moduix-spacing-4);
    inset-inline-end: var(--moduix-spacing-4);
  }

  .control {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--moduix-spacing-2);
    margin-block-start: var(--moduix-spacing-3);
  }

  .actionTrigger {
    --_tour-action-bg-hover: var(--moduix-color-accent);
    box-sizing: border-box;
    display: inline-flex;
    min-height: var(--moduix-size-sm);
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    padding: var(--moduix-spacing-1-5) var(--moduix-spacing-3);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font: inherit;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    white-space: nowrap;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    &:is([data-type='next'], [data-type='close']) {
      --_tour-action-bg-hover: color-mix(in oklab, var(--moduix-color-primary), black 12%);
      border-color: transparent;
      background-color: var(--moduix-color-primary);
      color: var(--moduix-color-primary-foreground);
    }

    @media (hover: hover) {
      &:hover:not(:disabled) {
        background-color: var(--_tour-action-bg-hover);
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }

    &:disabled {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .backdrop[data-state],
    .content[data-state] {
      animation: none;
    }
  }
}
